 update public.bookish_submissions set payload=payload||jsonb_build_object('visibility',case when status='confirmed' and payload->>'list_in_city' is distinct from 'no' then 'open' else 'hidden' end) where kind in ('claim','start') and not(payload ? 'visibility');
 -- Retain the first legacy host capability, with its latest explicit preference.
 with first_owner as(select distinct on(club_ref) * from public.bookish_submissions where kind in ('claim','start') and status='confirmed' and club_ref is not null order by club_ref,confirmed_at nulls last,created_at,id)
 insert into public.bookish_clubs(club_ref,name,city,state,visibility,listed,owner_submission_id,public_data)
 select s.club_ref,left(coalesce(nullif(s.payload->>'club_name',''),'Book club'),140),left(coalesce(s.payload->>'city',s.payload->>'club_city'),80),upper(left(s.payload->>'state',2)),coalesce(s.payload->>'visibility','hidden'),coalesce(s.payload->>'visibility','hidden')<>'hidden',s.id,jsonb_build_object('genres',case when coalesce(s.payload->>'genre','')='' then '[]'::jsonb else jsonb_build_array(s.payload->>'genre') end,'cadence',s.payload->>'cadence','format',s.payload->>'format') from first_owner s
 on conflict(club_ref) where club_ref is not null do update set owner_submission_id=excluded.owner_submission_id,visibility=excluded.visibility,listed=excluded.listed where bookish_clubs.owner_submission_id is null and not exists(select 1 from public.bookish_members m where m.club_id=bookish_clubs.id and m.role in ('host','cohost'));
 -- Rotate old, potentially predictable directory invites through host tools.
 update public.bookish_invites set expires_at=now() where club_id is null;
 insert into bookish_release_20261101.state values('v11',now());
 end if;
end $seed$;
-- Explicit grants do not depend on Supabase's changing default privileges.
do $acl$ declare r record;begin
 for r in select tablename from pg_tables where schemaname='public' and tablename like 'bookish\_%' escape '\' loop
  execute format('alter table public.%I enable row level security',r.tablename);
  execute format('revoke all on public.%I from public,anon',r.tablename);
  execute format('grant select,insert,update,delete on public.%I to service_role',r.tablename);
 end loop;
end $acl$;
commit;
